fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // If sub would run off the end of main, it can't match.
    if start + sub.len() > main.len() {
        return false;
    }

    // Check element by element.
    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // The empty subarray is always considered a match.
    if sub.is_empty() {
        return true;
    }
    // If sub is longer than main, it can't possibly match.
    if sub.len() > main.len() {
        return false;
    }

    // Try every possible starting position.
    let last_start = main.len() - sub.len();
    for start in 0..=last_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }

    false
}

